const racesBy = `-- name: RacesBy :many
SELECT r.made_at, (CASE WHEN w.state = 'active' THEN r.state ELSE 'finished' END)::text AS state, r.kind
FROM race r
JOIN world w ON w.id = r.world_id
WHERE r.owner_id = $1 AND (r.made_at > $2 OR (r.state IN ('open', 'closed', 'racing') AND w.state = 'active'))
`

type RacesByParams struct {
	OwnerID pgtype.UUID
	Since   time.Time
}

type RacesByRow struct {
	MadeAt time.Time
	State  string
	Kind   string
}

// The races an owner made in any world since a time, or has not finished
// in the world sailed (a race of a world ended is over).
func (q *Queries) RacesBy(ctx context.Context, arg RacesByParams) ([]RacesByRow, error) {
	rows, err := q.db.Query(ctx, racesBy, arg.OwnerID, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RacesByRow
	for rows.Next() {
		var i RacesByRow
		if err := rows.Scan(&i.MadeAt, &i.State, &i.Kind); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const racesSailed = `-- name: RacesSailed :one
SELECT count(*)::integer FROM race_record
WHERE account_id = $1 AND kind = 'race' AND role IN ('skipper', 'crew') AND how IS DISTINCT FROM 'dns'
`

// How many races an account has sailed over every world, skipper or crew.
func (q *Queries) RacesSailed(ctx context.Context, accountID pgtype.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, racesSailed, accountID)
	var column_1 int32
	err := row.Scan(&column_1)
	return column_1, err
}

