const removeEntry = `-- name: RemoveEntry :one
UPDATE race_entry SET removed = true
WHERE world_id = $1 AND race_id = $2 AND number = $3 AND run = 0
  AND withdrawn_at IS NULL AND NOT removed
RETURNING account_id
`

