const setRaceSettings = `-- name: SetRaceSettings :exec
UPDATE setting SET race_ahead = $1, race_daily = $2, race_made = $3, race_owned = $4,
  race_cutoff = $5::bigint * interval '1 second', harbour_every = $6,
  harbour_boats = $7, greenhorn_us = $8
`

type SetRaceSettingsParams struct {
	RaceAhead     int16
	RaceDaily     int16
	RaceMade      int16
	RaceOwned     int16
	CutoffSeconds int64
	HarbourEvery  int16
	HarbourBoats  []string
	GreenhornUs   int16
}

// The racing limits and the harbour races' timetable, all at once.
